const sites = [
  { name: 'بيت الريف', url: 'https://bietalreef.ae', sitemap: 'https://bietalreef.ae/sitemap.xml', robots: 'https://bietalreef.ae/robots.txt' },
  { name: 'تطبيق بيت الريف', url: 'https://app.bietalreef.ae', sitemap: 'https://app.bietalreef.ae/sitemap.xml', robots: 'https://app.bietalreef.ae/robots.txt' },
  { name: 'وياك', url: 'https://weyaakai.bietalreef.ae', sitemap: 'https://weyaakai.bietalreef.ae/sitemap.xml', robots: 'https://weyaakai.bietalreef.ae/robots.txt' }
];

return [{
  json: {
    chatInput: `نفّذ مراجعة SEO/GEO تقنية للمواقع الثلاثة التالية فقط:
${sites.map((s,i)=>`${i+1}. ${s.name}: ${s.url}\n   robots: ${s.robots}\n   sitemap: ${s.sitemap}`).join('\n')}

المطلوب:
- استخدم أداة fetch_public_url لفحص الصفحة الرئيسية وrobots.txt وsitemap.xml لكل موقع.
- استخدم أداة pagespeed_audit لكل موقع على mobile وdesktop.
- تحقق من title وmeta description وcanonical وH1 وschema وrobots وsitemap وحالة الوصول.
- قارن المواقع الثلاثة وحدد المشاكل حسب الأولوية.
- لا تدّعِ أنك عدّلت Google Search Console؛ تحديث GSC يتم بعقد منفصلة بعد هذه المراجعة.
- أخرج النتيجة بالعربية مع ملخص تنفيذي وجدول لكل دومين وإجراءات P0/P1/P2.`,
    sites,
    gsc_property: 'sc-domain:bietalreef.ae',
    started_at: new Date().toISOString()
  }
}];

const agentOutput = $json.output || $json.text || $json;
const sites = [
  { site_name: 'بيت الريف', site_url: 'https://bietalreef.ae', sitemap_url: 'https://bietalreef.ae/sitemap.xml' },
  { site_name: 'تطبيق بيت الريف', site_url: 'https://app.bietalreef.ae', sitemap_url: 'https://app.bietalreef.ae/sitemap.xml' },
  { site_name: 'وياك', site_url: 'https://weyaakai.bietalreef.ae', sitemap_url: 'https://weyaakai.bietalreef.ae/sitemap.xml' }
];
return sites.map(site => ({
  json: {
    ...site,
    gsc_property: 'sc-domain:bietalreef.ae',
    agent_report: agentOutput,
    audited_at: new Date().toISOString()
  }
}));
